export function contourPoints(layer=0,seed=0){const p=[],r=45+layer*9;for(let i=0;i<160;i++){let a=i/160*Math.PI*2,d=1+.14*Math.sin(a*3+seed*.41)+.08*Math.cos(a*5-seed*.3)+.045*Math.sin(a*9+layer*.08);p.push([600+Math.cos(a)*r*d*1.45+layer*.8,400+Math.sin(a)*r*d*.83-layer*2.2])}p.push([...p[0]]);return p}
export function contourSVG(seed=0){const paths=Array.from({length:31},(_,i)=>`<path d="${contourPoints(i,seed).map((p,j)=>(j?'L':'M')+p.map(v=>v.toFixed(2)).join(',')).join(' ')}Z" fill="none" stroke="${i%5===0?'#ecddac':'#78958c'}" stroke-width="${i%5===0?1.9:1}"/>`).join('');return `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="800" viewBox="0 0 1200 800"><rect width="1200" height="800" fill="#152f31"/>${paths}<circle cx="600" cy="400" r="7" fill="#ed784e"/><g fill="#d6d5b8" font-family="monospace"><text x="44" y="62" font-size="15" letter-spacing="3">CONTOUR / ${String(seed).padStart(2,'0')}</text><text x="44" y="750" font-size="12" letter-spacing="2">AN IMAGINARY LANDSCAPE · NOT GEOGRAPHIC DATA</text></g></svg>`}
